const legacyBySchool = new Map<string, { key: string; name: string; nativeName: string }>(
  legacy.map(([tournamentId, school, key, name, nativeName]) => [
    `${tournamentId}-${school}`, { key, name, nativeName },
  ]),
);

export const JAPAN_AFFILIATIONS: readonly AmateurAffiliation[] = rosters.flatMap(([tournamentId, region, schools]) => {
  const sourceUrl = `https://smart.asahi.com/v/koshien/game/2026/${tournamentId}/index.php`;
  return schools.map(([school, koreanName, searchAliases]) => {
    const schoolKey = `${tournamentId}-${school}`;
    const existing = legacyBySchool.get(schoolKey);
    return {
      id: `jp-${existing?.key ?? schoolKey}`,
      country: "JP",
      kind: "school",
      name: existing?.name ?? koreanName,
      nativeName: existing?.nativeName ?? school,
      searchAliases: [school, ...searchAliases],
      region,
      sourceUrl,
    };
  });
});

